        // panduan sambung HP
        ["Langkah {0} dari {1}"] = "Step {0} of {1}", ["Langkah 1 dari 4"] = "Step 1 of 4", ["Langkah 2 dari 4"] = "Step 2 of 4", ["Langkah 3 dari 4"] = "Step 3 of 4", ["Langkah 4 dari 4"] = "Step 4 of 4",
        ["Pasang aplikasi ZaxLet HP"] = "Install the ZaxLet phone app",
        ["Pindai kode ini dengan kamera HP (HP dan laptop harus di Wi-Fi yang sama), buka berkas yang terunduh, lalu izinkan pemasangan dari sumber ini bila Android bertanya."] = "Scan this code with your phone camera (phone and laptop must be on the same Wi-Fi), open the downloaded file, then allow installing from this source if Android asks.",
        ["1. Unduh aplikasi (APK)"] = "1. Download the app (APK)",
        ["Server sambungan HP belum menyala"] = "The phone connection server is not on", ["○ Server sambungan HP belum menyala"] = "○ The phone connection server is not on",
        ["Nyalakan server HP"] = "Turn on the phone server",
        ["Pasangkan HP ke laptop"] = "Pair the phone with the laptop",
        ["Buka aplikasi ZaxLet HP lalu pindai kode ini (atau pindai dengan kamera HP, aplikasinya terbuka sendiri). Cukup sekali; setelahnya tersambung otomatis."] = "Open the ZaxLet phone app and scan this code (or scan with the phone camera and the app opens by itself). Only needed once; afterwards it connects automatically.",
        ["Izinkan notifikasi"] = "Allow notifications",
        ["Di aplikasi ZaxLet HP, ketuk Izinkan akses notifikasi lalu aktifkan ZaxLet HP di daftar Android. Matikan juga penghemat baterai untuk aplikasi ini supaya sambungan tidak terputus. Pilih aplikasi mana saja yang ditampilkan di Pengaturan > HP."] = "In the ZaxLet phone app, tap Allow notification access, then enable ZaxLet in Android's list. Also turn off battery saver for this app so the connection is not cut. Choose which apps are shown in Settings > Phone.",
        ["Kirim notifikasi contoh"] = "Send a sample notification", ["Belum ada notifikasi dari HP"] = "No notification from the phone yet",
        ["Kalau tidak tersambung"] = "If it does not connect",
        ["Periksa berurutan: (1) HP dan laptop di Wi-Fi yang sama. Wi-Fi tamu atau publik sering memblokir antar perangkat; pakai hotspot HP atau Tailscale. (2) Saat Windows menanyakan firewall, pilih Izinkan. (3) Setelah ganti jaringan, pindai ulang kode pasangan."] = "Check in order: (1) Phone and laptop on the same Wi-Fi. Guest or public Wi-Fi often blocks device-to-device traffic; use the phone's hotspot or Tailscale. (2) When Windows asks about the firewall, choose Allow. (3) After changing networks, scan the pairing code again.",
        ["Nyalakan ulang server HP"] = "Restart the phone server",
        ["{0} HP tersambung"] = "{0} phone(s) connected", ["Menunggu aplikasi HP"] = "Waiting for the phone app", ["Tersambung · voice: {0}"] = "Connected · voice: {0}",

        // panduan Discord
        ["Langkah 1 dari 5"] = "Step 1 of 5", ["Langkah 2 dari 5"] = "Step 2 of 5", ["Langkah 3 dari 5"] = "Step 3 of 5", ["Langkah 4 dari 5"] = "Step 4 of 5", ["Langkah 5 dari 5"] = "Step 5 of 5",
        ["Mic dan Deafen di island"] = "Mic and Deafen from the island",
        ["Ada dua cara. Cara cepat tidak perlu pengaturan: ZaxLet memfokuskan Discord sebentar lalu menekan pintasan bawaannya (Ctrl+Shift+M mic, Ctrl+Shift+D deafen); Discord harus terbuka. Cara lengkap menyambungkan ZaxLet ke Discord sekali supaya status voice channel dan tombol Keluar VC ikut bekerja, tanpa berpindah jendela."] = "There are two ways. The quick way needs no setup: ZaxLet briefly focuses Discord and presses its default shortcuts (Ctrl+Shift+M mic, Ctrl+Shift+D deafen); Discord must be open. The full way connects ZaxLet to Discord once so the voice channel status and the Leave VC button work too, without switching windows.",
        ["Cara cepat siap dipakai; cara lengkap belum disiapkan"] = "Quick way is ready; full way is not set up yet",
        ["Cara cepat: cek pintasan"] = "Quick way: check the shortcuts",
        ["Buka Discord (aplikasi desktop), masuk ke voice channel, lalu tekan tombol Mic atau Deafen di tab Komunikasi. Kalau tidak bereaksi, di Discord buka Pengaturan Pengguna > Keybind dan pastikan pintasannya sama dengan di ZaxLet (Pengaturan > Alat > Pintasan Discord dan Meet). Selesai di sini bila itu cukup."] = "Open Discord (the desktop app), join a voice channel, then press the Mic or Deafen button in the Communication tab. If nothing happens, open User Settings > Keybinds in Discord and make sure the shortcuts match ZaxLet's (Settings > Tools > Discord and Meet shortcuts). You can stop here if that is enough.",
        ["Cara lengkap 1: buat aplikasi Discord"] = "Full way 1: create a Discord application",
        ["Buka portal developer Discord (gratis, tidak ada yang dipublikasikan). Klik New Application dan beri nama bebas, lalu di menu OAuth2 klik Add Redirect, tempel http://localhost, dan Save. Tombol di bawah membantu."] = "Open the Discord developer portal (free, nothing is published). Click New Application and give it any name, then in the OAuth2 menu click Add Redirect, paste http://localhost, and Save. The buttons below help.",
        ["Salin http://localhost"] = "Copy http://localhost",
        ["Cara lengkap 2: salin Client ID dan Secret"] = "Full way 2: copy the Client ID and Secret",
        ["Di halaman aplikasimu klik Copy pada Client ID, lalu klik Reset Secret dan Copy pada Secret. ZaxLet membaca clipboard otomatis dan mencentang di bawah; tidak perlu menempelkan apa pun."] = "On your application page click Copy on Client ID, then click Reset Secret and Copy on Secret. ZaxLet reads the clipboard automatically and ticks the boxes below; you do not need to paste anything.",
        ["○ Client ID"] = "○ Client ID", ["○ Secret"] = "○ Secret",
        ["Cara lengkap 3: izinkan di Discord"] = "Full way 3: authorize in Discord",
        ["Setelah keduanya tercentang, Discord menampilkan dialog Authorize. Klik Authorize. Status di bawah berubah hijau saat tersambung; sesudahnya Mic, Deafen, dan Keluar VC di tab Komunikasi bekerja langsung tanpa berpindah jendela."] = "Once both are ticked, Discord shows an Authorize dialog. Click Authorize. The status below turns green when connected; after that Mic, Deafen and Leave VC in the Communication tab work directly without switching windows.",

